export {
  inputClassName as baseUiComboboxInputClassName,
  buttonClassName as baseUiComboboxButtonClassName,
  itemsClassName as baseUiComboboxItemsClassName,
  itemClassName as baseUiComboboxItemClassName,
  backdropClassName as baseUiComboboxBackdropClassName,
  wrapperClassName as baseUiComboboxWrapperClassName,
} from "../combobox/view";

import { describe, expect, test } from "vitest";

import * as Combobox from "./index";

describe("Base UI Combobox registry view", () => {
  test("reuses the Foldkit Combobox functional contract", () => {
    expect(Combobox.init).toBeTypeOf("function");
    expect(Combobox.create).toBeTypeOf("function");
    expect(Combobox.Multi.create).toBeTypeOf("function");
    expect(Combobox.baseUiComboboxWrapperClassName).toContain("relative");
  });
});
